import {
  Pagination as PaginationPrimitive,
  usePagination,
  usePaginationContext,
} from '@ark-ui/solid/pagination';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, For, splitProps } from 'solid-js';
import { ChevronLeftIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './Pagination.module.css';

function PaginationRoot(props: ComponentProps<typeof PaginationPrimitive.Root>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <PaginationPrimitive.Root
      asChild={local.asChild}
      data-slot="pagination-root"
      class={clsx(styles.root, local.class)}
      {...others}
    >
      {local.children}
    </PaginationPrimitive.Root>
  );
}

function PaginationRootProvider(props: ComponentProps<typeof PaginationPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <PaginationPrimitive.RootProvider
      asChild={local.asChild}
      data-slot="pagination-root-provider"
      class={clsx(styles.root, local.class)}
      {...others}
    >
      {local.children}
    </PaginationPrimitive.RootProvider>
  );
}

function PaginationItem(props: ComponentProps<typeof PaginationPrimitive.Item>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <PaginationPrimitive.Item
      asChild={local.asChild}
      data-slot="pagination-item"
      class={clsx(styles.item, local.class)}
      {...others}
    />
  );
}

function PaginationEllipsis(props: ComponentProps<typeof PaginationPrimitive.Ellipsis>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PaginationPrimitive.Ellipsis
      asChild={local.asChild}
      data-slot="pagination-ellipsis"
      class={clsx(styles.ellipsis, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (!local.asChild && '...')}
    </PaginationPrimitive.Ellipsis>
  );
}

function EdgeIcon(props: { side: 'left' | 'right' }) {
  return (
    <span class={styles.edgeIcon} aria-hidden>
      {props.side === 'left' ? <ChevronLeftIcon /> : <ChevronRightIcon />}
      {props.side === 'left' ? <ChevronLeftIcon /> : <ChevronRightIcon />}
    </span>
  );
}

function PaginationPrevTrigger(props: ComponentProps<typeof PaginationPrimitive.PrevTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PaginationPrimitive.PrevTrigger
      asChild={local.asChild}
      data-slot="pagination-prev-trigger"
      class={clsx(styles.trigger, local.children == null && styles.iconTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (!local.asChild && <ChevronLeftIcon />)}
    </PaginationPrimitive.PrevTrigger>
  );
}

function PaginationNextTrigger(props: ComponentProps<typeof PaginationPrimitive.NextTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PaginationPrimitive.NextTrigger
      asChild={local.asChild}
      data-slot="pagination-next-trigger"
      class={clsx(styles.trigger, local.children == null && styles.iconTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (!local.asChild && <ChevronRightIcon />)}
    </PaginationPrimitive.NextTrigger>
  );
}

function PaginationFirstTrigger(props: ComponentProps<typeof PaginationPrimitive.FirstTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PaginationPrimitive.FirstTrigger
      asChild={local.asChild}
      data-slot="pagination-first-trigger"
      class={clsx(styles.trigger, local.children == null && styles.iconTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (!local.asChild && <EdgeIcon side="left" />)}
    </PaginationPrimitive.FirstTrigger>
  );
}

function PaginationLastTrigger(props: ComponentProps<typeof PaginationPrimitive.LastTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <PaginationPrimitive.LastTrigger
      asChild={local.asChild}
      data-slot="pagination-last-trigger"
      class={clsx(styles.trigger, local.children == null && styles.iconTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (!local.asChild && <EdgeIcon side="right" />)}
    </PaginationPrimitive.LastTrigger>
  );
}

const PaginationContext = PaginationPrimitive.Context;

function PaginationItems() {
  return (
    <PaginationContext>
      {(pagination) => (
        <For each={pagination().pages}>
          {(page, index) =>
            page.type === 'page' ? (
              <PaginationItem {...page}>{page.value}</PaginationItem>
            ) : (
              <PaginationEllipsis index={index()} />
            )
          }
        </For>
      )}
    </PaginationContext>
  );
}

type PaginationComponent = typeof PaginationRoot & {
  Root: typeof PaginationRoot;
  RootProvider: typeof PaginationRootProvider;
  Item: typeof PaginationItem;
  Ellipsis: typeof PaginationEllipsis;
  PrevTrigger: typeof PaginationPrevTrigger;
  NextTrigger: typeof PaginationNextTrigger;
  FirstTrigger: typeof PaginationFirstTrigger;
  LastTrigger: typeof PaginationLastTrigger;
  Context: typeof PaginationContext;
  Items: typeof PaginationItems;
  usePagination: typeof usePagination;
  usePaginationContext: typeof usePaginationContext;
};

const Pagination: PaginationComponent = Object.assign(PaginationRoot, {
  Root: PaginationRoot,
  RootProvider: PaginationRootProvider,
  Item: PaginationItem,
  Ellipsis: PaginationEllipsis,
  PrevTrigger: PaginationPrevTrigger,
  NextTrigger: PaginationNextTrigger,
  FirstTrigger: PaginationFirstTrigger,
  LastTrigger: PaginationLastTrigger,
  Context: PaginationContext,
  Items: PaginationItems,
  usePagination,
  usePaginationContext,
});

export { Pagination, usePagination, usePaginationContext };

@layer moduix.components {
  .root {
    display: inline-flex;
    align-items: center;
    max-inline-size: 100%;
    gap: var(--moduix-pagination-gap, var(--moduix-spacing-1));
    overflow-x: auto;
    color: var(--moduix-pagination-color, var(--moduix-color-foreground));
  }

  .item,
  .trigger,
  .ellipsis {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--moduix-pagination-item-size, var(--moduix-size-md));
    height: var(--moduix-pagination-item-size, var(--moduix-size-md));
    border-radius: var(--moduix-pagination-item-radius, var(--moduix-radius-md));
    font-size: var(--moduix-pagination-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-pagination-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-pagination-line-height, var(--moduix-line-height-text-sm));
    font-variant-numeric: tabular-nums;
  }

  .item,
  .trigger {
    cursor: pointer;
    gap: var(--moduix-pagination-trigger-gap, var(--moduix-spacing-2));
    border: var(--moduix-pagination-item-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-pagination-item-border-color, var(--moduix-color-border));
    padding-inline: var(--moduix-pagination-item-padding-inline, var(--moduix-spacing-2));
    background-color: var(--moduix-pagination-item-bg, var(--moduix-color-background));
    color: var(--moduix-pagination-item-color, var(--moduix-color-foreground));
    font-family: inherit;
    text-decoration: none;
    user-select: none;
    white-space: nowrap;

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-pagination-item-bg-hover, var(--moduix-color-accent));
      }
    }

    &:focus-visible {
      outline: var(
          --moduix-pagination-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-pagination-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(
        --moduix-pagination-focus-ring-offset,
        var(--moduix-focus-ring-inset-offset)
      );
    }

    &:is([data-disabled], :disabled) {
      opacity: var(--moduix-pagination-disabled-opacity, var(--moduix-opacity-disabled));
      pointer-events: none;
    }

    & svg {
      flex-shrink: 0;
      width: var(--moduix-pagination-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-pagination-icon-size, var(--moduix-spacing-4));
    }
  }

  .item[data-selected] {
    border-color: var(
      --moduix-pagination-item-border-color-selected,
      var(--moduix-color-foreground)
    );
    background-color: var(--moduix-pagination-item-bg-selected, var(--moduix-color-foreground));
    color: var(--moduix-pagination-item-color-selected, var(--moduix-color-background));

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-pagination-item-bg-selected, var(--moduix-color-foreground));
      }
    }
  }

  .trigger {
    padding-inline: max(
      var(--moduix-pagination-item-padding-inline, var(--moduix-spacing-3)),
      var(--moduix-spacing-3)
    );
  }

  .iconTrigger {
    width: var(--moduix-pagination-item-size, var(--moduix-size-md));
    padding-inline: 0;

    &:dir(rtl) svg {
      transform: scaleX(-1);
    }
  }

  .ellipsis {
    color: var(--moduix-pagination-ellipsis-color, var(--moduix-color-muted-foreground));
    user-select: none;
  }

  .edgeIcon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    & svg + svg {
      margin-inline-start: calc(var(--moduix-pagination-icon-size, var(--moduix-spacing-4)) * -0.5);
    }
  }
}
